<?php $today=count(array_filter($all,fn($b)=>$b['date']===date('Y-m-d')&&in_array($b['status'],['Pendente','Confirmado'],true))); ?>
<section class="stat-grid admin-stats"><?php foreach([['Salas ativas',count(array_filter($rooms,fn($r)=>$r['status']!=='Manutenção')),'Ambientes em atividade','door-open'],['Reservas hoje',$today,'Atividades programadas','calendar-days'],['Pendentes',count($pending),'Aguardam aprovação','circle-alert'],['Professores',$userCount,'Professores cadastrados','users']] as [$label,$value,$help,$i]): ?><article class="stat-card"><div class="stat-top"><p><?= e($label) ?></p><span class="stat-icon"><?= icon($i) ?></span></div><strong><?= $value ?></strong><small><?= e($help) ?></small></article><?php endforeach; ?></section>
<div class="dashboard-grid"><section class="card"><header class="card-heading"><h3>Aprovações pendentes <span class="count-pill"><?= count($pending) ?></span></h3><a class="text-link" href="<?= e(url('approvals')) ?>">Ver todas <?= icon('chevron-right') ?></a></header><?php foreach(array_slice($pending,0,3) as $b): ?><article class="pending-row"><div class="grow"><h4><?= e($b['room_name']) ?></h4><p><?= e($b['purpose']) ?></p><small><?= e($b['teacher']) ?> · <?= e(date_br($b['date'])) ?> · <?= e(substr($b['start_time'],0,5).'–'.substr($b['end_time'],0,5)) ?></small></div><div class="actions"><?php foreach(['approve'=>['check','Aprovar'],'reject'=>['x','Recusar']] as $act=>[$i,$label]): ?><form method="post" action="<?= e(url('approvals',['action'=>$act,'id'=>$b['id']])) ?>" <?= $act==='reject'?'data-confirm="Recusar esta solicitação de reserva?"':'' ?>><?= csrf_field() ?><button class="icon-button soft-button" title="<?= $label ?>" aria-label="<?= e($label.' '.$b['room_name']) ?>"><?= icon($i) ?></button></form><?php endforeach; ?></div></article><?php endforeach;if(!$pending){empty_state('Tudo em dia!','Nenhuma solicitação aguarda aprovação.');} ?></section>
<section class="card"><header class="card-heading"><h3>Ocupação das salas</h3></header><div class="card-body occupancy"><?php foreach($rooms as $r): $hours=0;foreach($all as $b){if((int)$b['room_id']===(int)$r['id']&&$b['status']==='Confirmado'&&$b['date']>=$weekStart&&$b['date']<=date('Y-m-d',strtotime($weekStart.' +4 days'))){$hours+=(strtotime($b['end_time'])-strtotime($b['start_time']))/3600;}} $percent=min(100,(int)round($hours/55*100)); ?><div><div class="row-title"><span><?= e($r['name']) ?></span><span><?= $percent ?>%</span></div><progress max="100" value="<?= $percent ?>" aria-label="Ocupação de <?= e($r['name']) ?>"><?= $percent ?>%</progress></div><?php endforeach; ?><small>Horas confirmadas nesta semana · 7h às 18h</small></div></section></div>
<section class="card section-gap"><header class="card-heading"><h3>Visão da semana — Salas mais usadas</h3><a class="text-link" href="<?= e(url('calendar')) ?>">Calendário completo <?= icon('chevron-right') ?></a></header><div class="table-scroll"><table class="week-overview"><thead><tr><th>Sala</th><?php foreach(['Seg','Ter','Qua','Qui','Sex'] as $offset=>$label): ?><th><?= $label ?><small><?= date('d/m',strtotime($weekStart.' +'.$offset.' days')) ?></small></th><?php endforeach; ?></tr></thead><tbody><?php foreach(array_slice($rooms,0,4) as $r): ?><tr><td><?= e($r['name']) ?></td><?php for($d=0;$d<5;$d++): $date=date('Y-m-d',strtotime($weekStart.' +'.$d.' days'));$occupied=count(array_filter($all,fn($b)=>(int)$b['room_id']===(int)$r['id']&&$b['date']===$date&&in_array($b['status'],['Confirmado','Pendente'],true)))>0; ?><td><?= badge($occupied?'Ocupado':'Livre') ?></td><?php endfor; ?></tr><?php endforeach; ?></tbody></table></div></section>

